package com.tecsup.model; import jakarta.persistence.*; @Entity public class Producto { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; public Long getId(){return id;} public void setId(Long v){id=v;}  private String nombre; public String getNombre(){return nombre;} public void setNombre(String v){this.nombre=v;} private Double precio; public Double getPrecio(){return precio;} public void setPrecio(Double v){this.precio=v;} private Integer stock; public Integer getStock(){return stock;} public void setStock(Integer v){this.stock=v;} private Long categoriaId; public Long getCategoriaId(){return categoriaId;} public void setCategoriaId(Long v){this.categoriaId=v;} }
